from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    q = deque([s])

    while q:
        u = q.popleft()
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                q.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
