def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    queue = [(s, 0)]
    visited = {s}

    while queue:
        node, dist = queue.pop(0)

        if node == t:
            return dist

        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + weight))

    return -1
