def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0

    visited = [False] * n

    for _ in range(n):
        min_dist = float('inf')
        min_node = -1

        for v in range(n):
            if not visited[v] and dist[v] < min_dist:
                min_dist = dist[v]
                min_node = v

        if min_node == -1:
            break

        visited[min_node] = True

        for neighbor, weight in graph[min_node]:
            if dist[neighbor] > dist[min_node] + weight:
                dist[neighbor] = dist[min_node] + weight

    if dist[t] == float('inf'):
        return 0
    else:
        return dist[t]
