    dist[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
