import heapq

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and
            0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    def get_neighbors(node):
        r, c = node
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                neighbors.append((nr, nc))
        return neighbors

    queue = [(0, start, [])]  # (cost, node, path)
    visited = set()

    while queue:
        cost, curr_node, path = heapq.heappop(queue)

        if curr_node == goal:
            return path + [curr_node]

        if curr_node in visited:
            continue
        visited.add(curr_node)

        for neighbor in get_neighbors(curr_node):
            heapq.heappush(queue, (cost + 1, neighbor, path + [curr_node]))

    return []
