    in_degree = [0] * n
    for pre, task in prerequisites:
        graph[task].append(pre)
        in_degree[pre] += 1

    queue = [i for i in range(n) if in_degree[i] == 0]
    result = []
    count = 0

    while queue:
        node = queue.pop(0)
        result.append(node)
        count += 1

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if count == n:
        return result
    else:
        return []
```

