import heapq

def solve(n, prerequisites):
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for u, v in prerequisites:
        graph[v].append(u)
        indegree[u] += 1

    q = []
    for i in range(n):
        if indegree[i] == 0:
            heapq.heappush(q, i)

    ans = []
    while q:
        u = heapq.heappop(q)
        ans.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(q, v)

    if len(ans) == n:
        return ans
    else:
        return []
```

