def solve(nums, target):
    """
    Given a sorted array of integers nums and an integer target,
    return the first and the last index of the target in nums.
    If the target does not exist in nums, return [-1, -1].
    """
    if not nums:
        return [-1, -1]

    first = -1
    last = -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            first = mid
            right = mid - 1  # Continue searching on the left side
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    if first == -1:
        return [-1, -1]

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            last = mid
            left = mid + 1  # Continue searching on the right side
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return [first, last]
